(581, 42, 'impact_blocks_0_impact_icon', '197'),
(582, 42, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(583, 42, 'impact_blocks_0_impact_title', 'Education for All'),
(584, 42, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(585, 42, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(586, 42, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(587, 42, 'impact_blocks_1_impact_icon', '196'),
(588, 42, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(589, 42, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(590, 42, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(591, 42, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(592, 42, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(593, 42, 'impact_blocks_2_impact_icon', '195'),
(594, 42, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(595, 42, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(596, 42, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(597, 42, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(598, 42, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(599, 42, 'impact_blocks_3_impact_icon', '198'),
(600, 42, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(601, 42, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(602, 42, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(603, 42, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(604, 42, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
