(1201, 178, 'impact_blocks_0_impact_icon', ''),
(1202, 178, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(1203, 178, 'impact_blocks_0_impact_title', 'Education for All'),
(1204, 178, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(1205, 178, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(1206, 178, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(1207, 178, 'impact_blocks_1_impact_icon', ''),
(1208, 178, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(1209, 178, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(1210, 178, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(1211, 178, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(1212, 178, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(1213, 178, 'impact_blocks_2_impact_icon', ''),
(1214, 178, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(1215, 178, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(1216, 178, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(1217, 178, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(1218, 178, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(1219, 178, 'impact_blocks_3_impact_icon', ''),
(1220, 178, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(1221, 178, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(1222, 178, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(1223, 178, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
