(1367, 180, 'banner_sub_title', 'Bringing Hope, Building Futures'),
(1368, 180, '_banner_sub_title', 'field_644b75743b9c5'),
(1369, 180, 'banner_texts', 'Fighting Poverty and Providing Opportunities for Underprivileged Children'),
