(1613, 182, 'banner_title', 'Ramdhanu'),
(1614, 182, '_banner_title', 'field_644b754c3b9c4'),
(1615, 182, 'banner_sub_title', 'Bringing Hope, Building Futures'),
(1616, 182, '_banner_sub_title', 'field_644b75743b9c5'),
(1617, 182, 'banner_texts', 'Fighting Poverty and Providing Opportunities for Underprivileged Children'),
