(1997, 188, 'banner_sub_title', 'Bringing Hope, Building Futures'),
(1998, 188, '_banner_sub_title', 'field_644b75743b9c5'),
(1999, 188, 'banner_texts', 'Fighting Poverty and Providing Opportunities for Underprivileged Children'),
(2000, 188, '_banner_texts', 'field_644b75883b9c6'),
