(2087, 188, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(2088, 188, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(2089, 188, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
