(2210, 189, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(2211, 189, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(2212, 189, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(2213, 189, 'impact_blocks_1_impact_icon', ''),
(2214, 189, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(2215, 189, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(2216, 189, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(2217, 189, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(2218, 189, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
