(2251, 190, 'banner_title', 'Ramdhanu'),
(2252, 190, '_banner_title', 'field_644b754c3b9c4'),
(2253, 190, 'banner_sub_title', 'Bringing Hope, Building Futures'),
(2254, 190, '_banner_sub_title', 'field_644b75743b9c5'),
(2255, 190, 'banner_texts', 'Fighting Poverty and Providing Opportunities for Underprivileged Children'),
(2256, 190, '_banner_texts', 'field_644b75883b9c6'),
