(2731, 199, 'impact_blocks_0_impact_icon', '197'),
(2732, 199, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(2733, 199, 'impact_blocks_0_impact_title', 'Education for All'),
(2734, 199, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(2735, 199, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(2736, 199, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(2737, 199, 'impact_blocks_1_impact_icon', '196'),
(2738, 199, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(2739, 199, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(2740, 199, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(2741, 199, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(2742, 199, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(2743, 199, 'impact_blocks_2_impact_icon', '195'),
(2744, 199, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(2745, 199, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(2746, 199, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(2747, 199, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(2748, 199, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(2749, 199, 'impact_blocks_3_impact_icon', '198'),
(2750, 199, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(2751, 199, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(2752, 199, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(2753, 199, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(2754, 199, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
