(5892, 413, 'all_causes_3_cause_texts', 'Serving Homeless and Underprivileged Communities with Compassion.'),
(5893, 413, '_all_causes_3_cause_texts', 'field_644bc424879c5'),
(5894, 413, 'all_causes_3_button_url', ''),
(5895, 413, '_all_causes_3_button_url', 'field_644bc439879c6'),
(5896, 413, 'impact_blocks_0_impact_icon', '197'),
(5897, 413, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(5898, 413, 'impact_blocks_0_impact_title', 'Education for All'),
(5899, 413, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(5900, 413, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(5901, 413, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(5902, 413, 'impact_blocks_1_impact_icon', '196'),
(5903, 413, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(5904, 413, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(5905, 413, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(5906, 413, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(5907, 413, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(5908, 413, 'impact_blocks_2_impact_icon', '195'),
(5909, 413, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(5910, 413, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(5911, 413, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(5912, 413, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(5913, 413, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(5914, 413, 'impact_blocks_3_impact_icon', '198'),
(5915, 413, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(5916, 413, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(5917, 413, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(5918, 413, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(5919, 413, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
