(6016, 414, 'all_causes_3_cause_tag', '#Compassion'),
(6017, 414, '_all_causes_3_cause_tag', 'field_644bc3fd879c3'),
(6018, 414, 'all_causes_3_cause_title', 'On The Street, For The Street'),
(6019, 414, '_all_causes_3_cause_title', 'field_644bc417879c4'),
(6020, 414, 'all_causes_3_cause_texts', 'Serving Homeless and Underprivileged Communities with Compassion.'),
(6021, 414, '_all_causes_3_cause_texts', 'field_644bc424879c5'),
(6022, 414, 'all_causes_3_button_url', ''),
(6023, 414, '_all_causes_3_button_url', 'field_644bc439879c6'),
(6024, 414, 'impact_blocks_0_impact_icon', '197'),
(6025, 414, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(6026, 414, 'impact_blocks_0_impact_title', 'Education for All'),
(6027, 414, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(6028, 414, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(6029, 414, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(6030, 414, 'impact_blocks_1_impact_icon', '196'),
(6031, 414, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(6032, 414, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(6033, 414, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(6034, 414, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(6035, 414, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(6036, 414, 'impact_blocks_2_impact_icon', '195'),
(6037, 414, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(6038, 414, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(6039, 414, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(6040, 414, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(6041, 414, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(6042, 414, 'impact_blocks_3_impact_icon', '198'),
(6043, 414, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(6044, 414, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(6045, 414, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(6046, 414, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(6047, 414, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
