(6914, 441, '_all_causes_3_cause_title', 'field_644bc417879c4'),
(6915, 441, 'all_causes_3_cause_texts', 'Serving Homeless and Underprivileged Communities with Compassion.'),
(6916, 441, '_all_causes_3_cause_texts', 'field_644bc424879c5'),
(6917, 441, 'all_causes_3_button_url', ''),
(6918, 441, '_all_causes_3_button_url', 'field_644bc439879c6'),
(6919, 441, 'impact_blocks_0_impact_icon', '197'),
(6920, 441, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(6921, 441, 'impact_blocks_0_impact_title', 'Education for All'),
(6922, 441, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(6923, 441, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(6924, 441, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(6925, 441, 'impact_blocks_1_impact_icon', '196'),
(6926, 441, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(6927, 441, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(6928, 441, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(6929, 441, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(6930, 441, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(6931, 441, 'impact_blocks_2_impact_icon', '195'),
(6932, 441, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(6933, 441, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(6934, 441, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(6935, 441, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(6936, 441, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(6937, 441, 'impact_blocks_3_impact_icon', '198'),
(6938, 441, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(6939, 441, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(6940, 441, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(6941, 441, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
