(7049, 442, 'impact_blocks_0_impact_title', 'Education for All'),
(7050, 442, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(7051, 442, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(7052, 442, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(7053, 442, 'impact_blocks_1_impact_icon', '196'),
(7054, 442, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(7055, 442, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(7056, 442, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(7057, 442, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(7058, 442, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
