(7062, 442, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(7063, 442, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(7064, 442, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
