(7618, 465, '_banner_title', 'field_644b754c3b9c4'),
(7619, 465, 'banner_sub_title', 'Bringing Hope, Building Futures'),
(7620, 465, '_banner_sub_title', 'field_644b75743b9c5'),
(7621, 465, 'banner_texts', 'Fighting Poverty and Providing Opportunities for Underprivileged Children'),
