(7831, 467, 'impact_blocks_0_impact_icon', '197'),
(7832, 467, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(7833, 467, 'impact_blocks_0_impact_title', 'Education for All'),
(7834, 467, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(7835, 467, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(7836, 467, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(7837, 467, 'impact_blocks_1_impact_icon', '196'),
(7838, 467, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(7839, 467, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(7840, 467, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(7841, 467, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(7842, 467, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(7843, 467, 'impact_blocks_2_impact_icon', '195'),
(7844, 467, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(7845, 467, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(7846, 467, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(7847, 467, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(7848, 467, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(7849, 467, 'impact_blocks_3_impact_icon', '198'),
(7850, 467, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(7851, 467, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(7852, 467, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(7853, 467, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
