(8313, 485, '_all_causes_3_cause_title', 'field_644bc417879c4'),
(8314, 485, 'all_causes_3_cause_texts', 'Serving Homeless and Underprivileged Communities with Compassion.'),
(8315, 485, '_all_causes_3_cause_texts', 'field_644bc424879c5'),
(8316, 485, 'all_causes_3_button_url', ''),
(8317, 485, '_all_causes_3_button_url', 'field_644bc439879c6'),
(8318, 485, 'impact_blocks_0_impact_icon', '197'),
(8319, 485, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(8320, 485, 'impact_blocks_0_impact_title', 'Education for All'),
(8321, 485, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(8322, 485, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(8323, 485, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(8324, 485, 'impact_blocks_1_impact_icon', '196'),
(8325, 485, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(8326, 485, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(8327, 485, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(8328, 485, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(8329, 485, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(8330, 485, 'impact_blocks_2_impact_icon', '195'),
(8331, 485, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(8332, 485, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(8333, 485, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(8334, 485, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(8335, 485, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(8336, 485, 'impact_blocks_3_impact_icon', '198'),
(8337, 485, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(8338, 485, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(8339, 485, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(8340, 485, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(8341, 485, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
