(8446, 486, 'impact_blocks_0_impact_icon', '197'),
(8447, 486, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(8448, 486, 'impact_blocks_0_impact_title', 'Education for All'),
(8449, 486, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(8450, 486, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(8451, 486, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(8452, 486, 'impact_blocks_1_impact_icon', '196'),
(8453, 486, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(8454, 486, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(8455, 486, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(8456, 486, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(8457, 486, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(8458, 486, 'impact_blocks_2_impact_icon', '195'),
(8459, 486, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(8460, 486, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(8461, 486, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(8462, 486, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(8463, 486, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(8464, 486, 'impact_blocks_3_impact_icon', '198'),
