(8466, 486, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(8467, 486, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(8468, 486, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
