(8609, 490, '_all_causes_3_button_url', 'field_644bc439879c6'),
(8610, 490, 'impact_blocks_0_impact_icon', '197'),
(8611, 490, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(8612, 490, 'impact_blocks_0_impact_title', 'Education for All'),
(8613, 490, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(8614, 490, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(8615, 490, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(8616, 490, 'impact_blocks_1_impact_icon', '196'),
(8617, 490, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(8618, 490, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(8619, 490, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(8620, 490, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(8621, 490, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(8622, 490, 'impact_blocks_2_impact_icon', '195'),
(8623, 490, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(8624, 490, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(8625, 490, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(8626, 490, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(8627, 490, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(8628, 490, 'impact_blocks_3_impact_icon', '198'),
(8629, 490, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(8630, 490, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(8631, 490, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(8632, 490, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(8633, 490, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
