(9227, 517, 'impact_blocks_0_impact_icon', '197'),
(9228, 517, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(9229, 517, 'impact_blocks_0_impact_title', 'Education for All'),
(9230, 517, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(9231, 517, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(9232, 517, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(9233, 517, 'impact_blocks_1_impact_icon', '196'),
(9234, 517, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(9235, 517, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(9236, 517, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(9237, 517, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(9238, 517, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(9239, 517, 'impact_blocks_2_impact_icon', '195'),
(9240, 517, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(9241, 517, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(9242, 517, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(9243, 517, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(9244, 517, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(9245, 517, 'impact_blocks_3_impact_icon', '198'),
(9246, 517, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(9247, 517, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(9248, 517, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(9249, 517, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(9250, 517, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
