(11228, 748, '_section_2_content_1_section_2_content_texts', 'field_644be78d78ed1'),
(11229, 748, 'section_2_content_1_section_2_content_tag', ''),
(11230, 748, '_section_2_content_1_section_2_content_tag', 'field_644be7a878ed2'),
(11231, 748, 'section_2_content_2_section_2_image', ''),
(11232, 748, '_section_2_content_2_section_2_image', 'field_644be75478ecf'),
(11233, 748, 'section_2_content_2_section_2_content_title', 'Public Art Projects'),
(11234, 748, '_section_2_content_2_section_2_content_title', 'field_644be76078ed0'),
(11235, 748, 'section_2_content_2_section_2_content_texts', 'Collaborative murals and community art projects bring color and life to public spaces while fostering teamwork and a sense of pride among the children. These projects often address social themes and encourage children to think critically about their surroundings.'),
(11236, 748, '_section_2_content_2_section_2_content_texts', 'field_644be78d78ed1'),
(11237, 748, 'section_2_content_2_section_2_content_tag', ''),
(11238, 748, '_section_2_content_2_section_2_content_tag', 'field_644be7a878ed2'),
(11239, 748, 'section_2_content_3_section_2_image', ''),
(11240, 748, '_section_2_content_3_section_2_image', 'field_644be75478ecf'),
(11241, 748, 'section_2_content_3_section_2_content_title', 'Art Therapy'),
(11242, 748, '_section_2_content_3_section_2_content_title', 'field_644be76078ed0'),
(11243, 748, 'section_2_content_3_section_2_content_texts', 'For children who have experienced trauma, art therapy sessions provide a safe and supportive environment to express their emotions and begin healing. These sessions are conducted by trained therapists who specialize in working with children.'),
(11244, 748, '_section_2_content_3_section_2_content_texts', 'field_644be78d78ed1'),
(11245, 748, 'section_2_content_3_section_2_content_tag', ''),
(11246, 748, '_section_2_content_3_section_2_content_tag', 'field_644be7a878ed2'),
(11247, 748, 'section_4_contents_0_section4_image', ''),
(11248, 748, '_section_4_contents_0_section4_image', 'field_644be8882741a'),
