(12568, 838, 'impact_blocks_0_impact_icon', '197'),
(12569, 838, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(12570, 838, 'impact_blocks_0_impact_title', 'Education for All'),
(12571, 838, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(12572, 838, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(12573, 838, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(12574, 838, 'impact_blocks_1_impact_icon', '196'),
(12575, 838, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(12576, 838, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(12577, 838, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(12578, 838, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(12579, 838, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(12580, 838, 'impact_blocks_2_impact_icon', '195'),
(12581, 838, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(12582, 838, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(12583, 838, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(12584, 838, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(12585, 838, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(12586, 838, 'impact_blocks_3_impact_icon', '198'),
(12587, 838, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(12588, 838, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(12589, 838, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(12590, 838, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
(12591, 838, '_impact_blocks_3_impact_texts', 'field_644bcb8ffa37d'),
