(12698, 839, 'impact_blocks_0_impact_title', 'Education for All'),
(12699, 839, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(12700, 839, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(12701, 839, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(12702, 839, 'impact_blocks_1_impact_icon', '196'),
(12703, 839, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(12704, 839, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(12705, 839, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(12706, 839, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(12707, 839, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(12708, 839, 'impact_blocks_2_impact_icon', '195'),
