(12956, 842, 'impact_blocks_0_impact_title', 'Education for All'),
(12957, 842, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(12958, 842, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(12959, 842, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(12960, 842, 'impact_blocks_1_impact_icon', '196'),
(12961, 842, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(12962, 842, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(12963, 842, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(12964, 842, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(12965, 842, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(12966, 842, 'impact_blocks_2_impact_icon', '195'),
(12967, 842, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(12968, 842, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(12969, 842, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(12970, 842, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(12971, 842, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(12972, 842, 'impact_blocks_3_impact_icon', '198'),
