(12975, 842, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(12976, 842, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
