(13309, 891, 'section_4_contents', '1'),
(13310, 891, '_section_4_contents', 'field_644be85327417'),
(13311, 891, 'section_2_content_0_section_2_image', '753'),
(13312, 891, '_section_2_content_0_section_2_image', 'field_644be75478ecf'),
(13313, 891, 'section_2_content_0_section_2_content_title', 'Art Workshops'),
(13314, 891, '_section_2_content_0_section_2_content_title', 'field_644be76078ed0'),
(13315, 891, 'section_2_content_0_section_2_content_texts', 'Regular workshops teach children painting, sketching, crafts, and digital art, led by professional artists and passionate volunteers.'),
(13316, 891, '_section_2_content_0_section_2_content_texts', 'field_644be78d78ed1'),
(13317, 891, 'section_2_content_0_section_2_content_tag', ''),
