(14765, 934, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(14766, 934, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
