(15597, 953, 'impact_blocks_0_impact_icon', '197'),
(15598, 953, '_impact_blocks_0_impact_icon', 'field_644bcb6bfa37b'),
(15599, 953, 'impact_blocks_0_impact_title', 'Education for All'),
(15600, 953, '_impact_blocks_0_impact_title', 'field_644bcb7ffa37c'),
(15601, 953, 'impact_blocks_0_impact_texts', 'We have successfully enrolled 24 street children in schools and provided them with educational materials, professional educators and guidance, paving the way for a brighter future for these children.'),
(15602, 953, '_impact_blocks_0_impact_texts', 'field_644bcb8ffa37d'),
(15603, 953, 'impact_blocks_1_impact_icon', '196'),
(15604, 953, '_impact_blocks_1_impact_icon', 'field_644bcb6bfa37b'),
(15605, 953, 'impact_blocks_1_impact_title', 'Health and Hygiene'),
(15606, 953, '_impact_blocks_1_impact_title', 'field_644bcb7ffa37c'),
(15607, 953, 'impact_blocks_1_impact_texts', 'Our medical camps have addressed the health and hygiene issues of children living on the streets, with special attention given to girls attaining puberty. We have also provided basic hygiene supplies to help them stay healthy.'),
(15608, 953, '_impact_blocks_1_impact_texts', 'field_644bcb8ffa37d'),
(15609, 953, 'impact_blocks_2_impact_icon', '195'),
(15610, 953, '_impact_blocks_2_impact_icon', 'field_644bcb6bfa37b'),
(15611, 953, 'impact_blocks_2_impact_title', 'Beyond Boundaries'),
(15612, 953, '_impact_blocks_2_impact_title', 'field_644bcb7ffa37c'),
(15613, 953, 'impact_blocks_2_impact_texts', 'Our initiative to visit remote areas to educate destitute children and distribute food has made a significant impact on the lives of tribal children in Murgaboni, Birbhum.'),
(15614, 953, '_impact_blocks_2_impact_texts', 'field_644bcb8ffa37d'),
(15615, 953, 'impact_blocks_3_impact_icon', '198'),
(15616, 953, '_impact_blocks_3_impact_icon', 'field_644bcb6bfa37b'),
(15617, 953, 'impact_blocks_3_impact_title', 'Ray of Hope'),
(15618, 953, '_impact_blocks_3_impact_title', 'field_644bcb7ffa37c'),
(15619, 953, 'impact_blocks_3_impact_texts', 'We work with blind children through our \"Ray of Hope\" project, providing them with basic necessities and education, helping them lead better lives.'),
